      "Docker 中常见链路是 dockerd 调用 containerd，containerd 管理镜像、快照、容器生命周期和 shim，底层再调用 runc 按 OCI Runtime Specification 创建容器进程。",
      "containerd 属于高层运行时，负责容器生命周期接口和本地运行管理；runc 属于低层 OCI 运行时，负责执行 create、start、kill、delete 等底层动作。",
      "Kubernetes 通过 CRI 与容器运行时交互。containerd 可以作为 Kubernetes 节点运行时，因此 Docker Engine、Kubernetes 和其他平台都能围绕相同的 OCI 镜像与运行时规范协作。",
      "运行时的关键对象包括 image、snapshot、container、task 和 namespace。containerd namespace 用于隔离不同上层系统的对象，例如 Docker 和 Kubernetes 可以使用各自的命名空间。",
      "docker info 可以看到当前 Engine 使用的运行时、默认 runtime、cgroup driver、存储驱动等信息。排查时还可以结合 ctr、crictl、journalctl 和容器事件查看底层状态。",
      "常见故障包括 runtime binary 缺失、containerd 未运行、shim 残留、snapshotter 异常、OCI spec 生成错误、cgroup 或权限配置异常、Kubernetes CRI 配置与节点 cgroup driver 组合不一致。",
      "运行时选择会影响隔离强度和兼容性。runc 是通用默认选择，gVisor、Kata Containers 等沙箱运行时会提供更强隔离，同时带来性能、特性和调试方式差异。",
      "参考来源：本讲解参考 containerd 文档、containerd 项目介绍、containerd Namespaces、runc、OCI Runtime Specification、Kubernetes Container Runtimes、Kubernetes CRI、Docker Engine 和《Docker 从入门到实践》的架构说明。",
