    zh: "联合文件系统",
    en: "Union File System",
    area: "image",
    difficulty: "medium",
    concept: "联合文件系统把多个只读层和一个可写层合并成容器看到的单一文件系统视图。",
    explanation: [
      "联合文件系统是一类把多个目录层叠加成统一目录树的文件系统技术。Docker 借助它把镜像只读层和容器可写层组合起来，让容器看到完整根文件系统。",
      "在 Docker 中，存储驱动负责实现联合挂载。Linux 上常见的 overlay2 会把镜像层作为 lowerdir，把容器写入区域作为 upperdir，并通过 merged 目录暴露给容器进程。",
      "读取文件时，联合文件系统按层查找并返回最高层可见的版本。写入文件时，已有文件会先从只读层复制到可写层，再在可写层修改，这就是写时复制。",
      "删除文件时，联合文件系统通常使用 whiteout 标记遮蔽下层文件。下层数据仍存在于镜像层中，因此在后续层删除大文件通常不会真正缩小历史层体积。",
      "联合文件系统让多个容器共享同一批镜像层，节省磁盘和拉取时间。容器自己的变更集中在可写层，删除容器时可写层会随容器生命周期清理。",
      "这个机制适合运行无状态应用和分发不可变镜像。高频写入数据库、队列数据、上传文件等持久数据应放到 volume 或 bind mount，避免依赖容器可写层。",
      "常见边界包括 storage driver 与内核版本兼容、overlay2 对底层文件系统有要求、容器可写层膨胀、inode 耗尽、写放大、跨层删除造成空间判断偏差。",
      "排查时先用 docker info 查看 Storage Driver，再用 docker image inspect、docker history、docker system df 和宿主机磁盘指标判断层、容器可写层和卷的占用来源。",
      "参考来源：本讲解参考 Docker Storage drivers、OverlayFS storage driver、Select a storage driver、Docker What is an image、docker image inspect、docker image history、《Docker 从入门到实践》联合文件系统和架构说明。",
    ],
