    concept: "容器文件系统由镜像只读层、容器可写层和挂载点组成，负责承载进程看到的目录结构与运行时写入。",
    explanation: [
      "容器启动后会把镜像的只读层叠加成根文件系统，再为当前容器添加一个可写层。应用在容器内创建、修改、删除普通文件时，变化会落到这个可写层。",
      "写时复制是容器文件系统的关键机制。读取文件时直接使用下层镜像数据，首次修改已有文件时会复制到可写层再修改，因此写入性能、磁盘占用和层结构都受存储驱动影响。",
      "Docker 常用 storage driver 管理这些层，Linux 上常见实现包括 overlay2。不同驱动在性能、inode 使用、文件复制语义和宿主机文件系统要求上会有差异。",
      "容器删除时，可写层会随容器清理。数据库数据、上传文件、缓存和业务状态需要放到 volume、bind mount 或外部存储中，让生命周期脱离单个容器对象。",
      "volume 由 Docker 管理路径和生命周期，适合持久化数据；bind mount 直接使用宿主机路径，适合开发调试、挂载配置和读取宿主机文件。两者都会覆盖容器镜像中同路径的可见内容。",
      "docker diff 可以查看容器可写层相对镜像发生的文件变化；docker cp 可以在容器和宿主机之间复制文件；docker container inspect --size 可以观察可写层和根文件系统大小。",
      "docker commit 能把容器当前可写层保存成新镜像，适合临时取证或复现实验。工程交付应优先把变更写回 Dockerfile、构建上下文和配置管理，保证镜像来源清晰。",
      "常见边界包括容器写满宿主机磁盘、可写层性能低于 volume、挂载覆盖镜像内默认文件、文件权限或 UID/GID 不匹配、Rootless 模式路径变化、SELinux/AppArmor 限制、跨平台路径格式差异。",
      "参考来源：本讲解参考 Docker Storage、Storage drivers、OverlayFS driver、docker container diff/cp/commit、Volumes、Bind mounts 和 docker container inspect 官方文档。",
    ],
